<template>
  <q-layout view="lHh Lpr lFf" class="drafting-layout">
    <q-page-container>
      <q-page class="drafting-page article-page">
        <header class="home-header"><div class="home-header-inner content-width"><div class="brand-lockup home-brand-lockup"><span class="brand-mark">UNESCAP</span><span class="brand-divider"></span><span class="brand-product"><strong>Digital Policy Drafting Platform</strong><small>Based on the AP-MDEA framework</small></span></div><nav class="home-nav" aria-label="Main navigation"><button class="home-nav-item home-nav-item--active" type="button" @click="router.push('/home')"><q-icon name="home" size="21px" /><span>Home</span></button><button class="home-nav-item" type="button" @click="notify('My Agreements is ready for the next mockup phase.')"><q-icon name="description" size="21px" /><span>My Agreements</span></button><button class="home-nav-item" type="button" @click="router.push('/home')"><q-icon name="library_books" size="21px" /><span>Templates</span></button><button class="home-nav-item" type="button" @click="notify('Resources is ready for the next mockup phase.')"><q-icon name="local_shipping" size="21px" /><span>Resources</span></button></nav><div class="home-actions"><button class="home-action-button" type="button" @click="notify('Help center is available in the production flow.')"><q-icon name="help_outline" size="21px" /><span>Help</span></button><span class="home-action-divider"></span><button class="user-menu" type="button" @click="notify('User menu is ready for the next mockup phase.')"><span class="user-avatar user-avatar--large">JD</span><span class="user-details"><strong>Jane Doe</strong><small>Policy Unit, Example Country</small></span><q-icon name="keyboard_arrow_down" size="18px" /></button></div></div></header>
        <main class="drafting-main content-width"><div class="drafting-breadcrumb"><button type="button" @click="router.push('/home')">Home</button><span>/</span><button type="button" @click="router.push('/home')">My Agreements</button><span>/</span><button type="button" @click="router.push('/templates/digital-economy-agreement')">{{ agreementTitle }}</button><span>/</span><button type="button" @click="router.push('/drafting-workspace')">Drafting Workspace</button><span>/</span><span>Article 2.5 - Cooperation and Review on Data Governance</span></div>
          <div class="drafting-grid article-drafting-grid"><aside class="outline-sidebar article-outline" aria-label="Agreement outline"><h2>Agreement outline</h2><button class="outline-module outline-module--active" type="button" @click="router.push('/drafting-workspace')"><span><strong>Module 2</strong><small>Data Governance</small></span><q-icon name="chevron_right" size="22px" /></button><div class="outline-articles"><button class="outline-article outline-article--complete" type="button" @click="router.push('/drafting-workspace/article-2.1')"><q-icon name="check_circle" size="21px" /><span><strong>Article 2.1</strong><small>Definitions</small></span></button><button class="outline-article outline-article--complete" type="button" @click="router.push('/drafting-workspace/article-2.2')"><q-icon name="check_circle" size="21px" /><span><strong>Article 2.2</strong><small>Cross-Border Transfer of Information by Electronic Means</small></span></button><button class="outline-article outline-article--complete" type="button" @click="router.push('/drafting-workspace/article-2.3')"><q-icon name="check_circle" size="21px" /><span><strong>Article 2.3</strong><small>Location of Computing Facilities</small></span></button><button class="outline-article outline-article--complete" type="button" @click="router.push('/drafting-workspace/article-2.4')"><q-icon name="check_circle" size="21px" /><span><strong>Article 2.4</strong><small>Financial Data</small></span></button><button class="outline-article outline-article--active" type="button"><q-icon name="description" size="22px" /><span><strong>Article 2.5</strong><small>Cooperation and Review on Data Governance</small></span></button></div></aside>
            <section class="drafting-center article-drafting-center"><div class="article-heading-row"><div><div class="article-context-label">Module 2 - Data Governance</div><div class="article-heading-line"><h1>Article 2.5 - Cooperation and Review on Data Governance</h1></div><p class="article-description">{{ article25.description }}</p></div></div><section class="article-progress-card"><div class="progress-icon drafting-icon drafting-icon--blue"><q-icon name="format_list_numbered" size="27px" /></div><div class="article-progress-copy"><strong>Articles completed: {{ completedArticlesCount }} of 5</strong><div class="article-progress-track"><span :style="{ width: `${completedArticlesCount / 5 * 100}%` }"></span></div></div><span class="article-progress-divider"></span><div class="next-article-copy"><strong>Module complete:</strong><span>This is the final article in Module 2.</span></div></section><div class="article-section-heading"><div><h2>1. Select cooperation mechanisms</h2><p>Choose one or more options. Option A and Option F cannot be selected together.</p></div><button v-if="selectedOptionCodes.length" class="clear-option-button" type="button" @click="clearOptions">Clear selection</button></div><div class="article-option-grid article25-option-grid"><article v-for="option in article25.options" :key="option.code" class="article-option-card" :class="{ 'article-option-card--selected': selectedOptionCodes.includes(option.code) }" @click="toggleOption(option.code)"><div class="option-card-heading"><span class="option-radio" :class="{ 'option-radio--selected': selectedOptionCodes.includes(option.code) }"><q-icon v-if="selectedOptionCodes.includes(option.code)" name="check" size="14px" /></span><div><small>{{ option.label }}</small><h3>{{ option.title }}</h3></div></div><p class="option-summary">{{ option.summary }}</p><dl class="option-details"><div><dt><q-icon name="group" size="18px" />Best for</dt><dd>{{ option.bestFor }}</dd></div><div><dt><q-icon name="account_balance" size="18px" />Financial scope</dt><dd>{{ option.financialScope }}</dd></div><div><dt><q-icon name="description" size="18px" />Source</dt><dd>{{ option.source }}</dd></div></dl></article></div><p v-if="selectedOptionCodes.length" class="article-selection-status">{{ selectedOptionCodes.length }} option{{ selectedOptionCodes.length === 1 ? '' : 's' }} selected{{ isCombinationValid ? '' : ' - Option A and Option F cannot be selected together.' }}</p><Article22ReferencesCard v-if="selectedReferences.length" :references="selectedReferences" @update:references="updateSelectedReferences" /><section v-if="!isCombinationValid" class="article-smart-callout article-smart-callout--requirement"><q-icon name="error_outline" size="27px" /><div><h2>Choose a valid combination</h2><p>Option A and Option F are alternatives and cannot be included in the same draft.</p></div></section><section v-if="selectedOptionCodes.includes('C')" class="article-smart-callout article-smart-callout--recommendation"><q-icon name="account_tree" size="27px" /><div><h2>Institutional mechanism needed</h2><p>Option C should be paired with a <strong>Joint Committee or another named institutional mechanism</strong> to run the standing dialogue.</p></div></section><section v-if="selectedOptionCodes.includes('D')" class="article-smart-callout article-smart-callout--recommendation"><q-icon name="event_repeat" size="27px" /><div><h2>Set the review cycle</h2><p>Option D requires a clear <strong>review cycle</strong>, including when the Parties will assess Articles 2.2-2.4.</p></div></section><section v-if="selectedOptionCodes.includes('E')" class="article-smart-callout article-smart-callout--recommendation"><q-icon name="verified_user" size="27px" /><div><h2>Check privacy compatibility</h2><p>Connect Option E to the <strong>privacy and personal-data regime compatibility</strong> framework used by the Parties.</p></div></section><div class="article-footer-actions"><button class="article-draft-button" type="button" @click="saveDraft">Save draft</button><button class="article-save-button" type="button" :disabled="!canCompleteArticle" @click="saveAndContinue">Complete Article 2.5<q-icon name="check" size="20px" /></button><button class="article-back-button" type="button" @click="router.push('/drafting-workspace')"><q-icon name="arrow_back" size="20px" />Back to module overview</button><span class="article-locked-note"><q-icon name="check_circle" size="18px" />Complete the final article<br />to finish Module 2.</span></div></section>
            <aside class="drafting-rail article-preview-rail"><section class="drafting-side-card article-preview-card article-preview-card--dynamic"><div class="side-card-heading article-preview-heading"><div class="drafting-icon drafting-icon--blue"><q-icon name="description" size="28px" /></div><h2>Draft preview</h2><button class="preview-expand-button" type="button" @click="openPreviewDialog"><q-icon name="open_in_full" size="16px" />View larger</button></div><div class="article-preview-title"><strong>{{ agreementTitle }}</strong><p>Draft - Module 2: Data Governance</p></div><div class="preview-article-current"><strong>{{ previewArticleHeading }}</strong><div class="preview-legal-text"><template v-for="(line, lineIndex) in previewArticleBody.split('\n')" :key="`preview-line-${lineIndex}`"><span>{{ line }}</span><br v-if="lineIndex < previewArticleBody.split('\n').length - 1" /></template></div></div><div class="preview-upcoming"><h3>Module status</h3><div class="preview-upcoming-article"><q-icon name="check_circle" size="16px" /><strong>Article 2.5 completes Module 2</strong></div></div></section></aside>
          </div>
        </main><footer class="dashboard-footer"><div class="dashboard-footer-inner content-width"><span>&copy; 2026 United Nations Economic and Social Commission for Asia and the Pacific (UNESCAP). All rights reserved.</span><nav aria-label="Footer links"><button type="button" @click="notify('Privacy Policy selected.')">Privacy Policy</button><i></i><button type="button" @click="notify('Terms of Use selected.')">Terms of Use</button><i></i><button type="button" @click="notify('Contact selected.')">Contact</button></nav></div></footer><q-dialog v-model="previewDialogOpen"><q-card class="preview-expand-dialog"><q-card-section class="preview-expand-heading"><div><div class="article-kicker">Draft preview</div><h2>{{ agreementTitle }}</h2><p>Draft - Module 2: Data Governance</p></div><q-btn flat round dense icon="close" aria-label="Close expanded preview" @click="previewDialogOpen = false" /></q-card-section><q-card-section class="preview-expand-body"><div class="preview-expand-current"><strong>{{ previewArticleHeading }}</strong><div class="preview-dialog-legal-text"><template v-for="(line, lineIndex) in previewArticleBody.split('\n')" :key="`dialog-line-${lineIndex}`"><span>{{ line }}</span><br v-if="lineIndex < previewArticleBody.split('\n').length - 1" /></template></div></div></q-card-section></q-card></q-dialog>
      </q-page>
    </q-page-container>
  </q-layout>
</template>

<script setup>
import { computed, nextTick, onMounted, onUpdated, ref } from 'vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import { article2_5 } from '../data/article2_5'
import Article22ReferencesCard from '../components/Article22ReferencesCard.vue'

const $q = useQuasar()
const router = useRouter()
const article25 = article2_5
const agreementTitle = ref(localStorage.getItem('agreementTitle') || 'Untitled agreement')
const selectedOptionCodes = ref(loadSelectedOptions())
const referencesByOption = ref(loadReferences())
const article21Completed = ref(localStorage.getItem('article-2.1-completed') === 'true')
const article22Completed = ref(localStorage.getItem('article-2.2-completed') === 'true')
const article23Completed = ref(localStorage.getItem('article-2.3-completed') === 'true')
const article24Completed = ref(localStorage.getItem('article-2.4-completed') === 'true')
const article25Completed = ref(localStorage.getItem('article-2.5-completed') === 'true')
const completedArticlesCount = computed(() => Number(article21Completed.value) + Number(article22Completed.value) + Number(article23Completed.value) + Number(article24Completed.value) + Number(article25Completed.value))
const selectedReferences = computed(() => selectedOptionCodes.value.flatMap((code) => referencesByOption.value[code] || []))
const resolvedReferenceCount = computed(() => selectedReferences.value.filter(resolveReference).length)
const isCombinationValid = computed(() => !(selectedOptionCodes.value.includes('A') && selectedOptionCodes.value.includes('F')))
const canCompleteArticle = computed(() => selectedOptionCodes.value.length > 0 && isCombinationValid.value && resolvedReferenceCount.value === selectedReferences.value.length)
const previewLegalText = computed(() => { if (!selectedOptionCodes.value.length) return `Article 2.5 - ${article25.title}\n\nSelect one or more options above to preview the draft text for this article.`; return selectedOptionCodes.value.map(renderOptionPreview).join('\n\n') })
const previewArticleHeading = computed(() => previewLegalText.value.split('\n')[0] || `Article 2.5 - ${article25.title}`)
const previewArticleBody = computed(() => previewLegalText.value.split('\n').slice(1).join('\n').replace(/^\n+/, ''))
const previewDialogOpen = ref(false)

function extractBracketedSegments(text) { const segments = []; let start = -1; let depth = 0; for (let index = 0; index < text.length; index += 1) { if (text[index] === '[') { if (depth === 0) start = index; depth += 1 } else if (text[index] === ']' && depth > 0) { depth -= 1; if (depth === 0) segments.push(text.slice(start, index + 1)) } } return segments }
function replaceBracketedSegments(text, replacer) { return extractBracketedSegments(text).reduce((result, bracketText) => result.replace(bracketText, replacer(bracketText)), text) }
function createReference(code, bracketText, index, existing = {}) { const choices = [{ value: 'placeholder', label: 'Keep as a drafting placeholder', hint: 'Can be finalized later', replacement: bracketText }]; return { optionCode: code, number: index + 1, key: `${code}-${index}`, label: 'Key term or institutional reference', bracketText, choices, source: existing.source || '', customReference: existing.customReference || '' } }
function loadSelectedOptions() { try { const saved = JSON.parse(localStorage.getItem('article-2.5-options-v1') || '[]'); return Array.isArray(saved) ? saved.filter((code) => article25.options.some((option) => option.code === code)) : [] } catch { return [] } }
function loadReferences() { try { const saved = JSON.parse(localStorage.getItem('article-2.5-references-v1') || '{}'); return Object.fromEntries(article25.options.map((option) => { const brackets = extractBracketedSegments(option.legalText); const existing = Array.isArray(saved[option.code]) ? saved[option.code] : []; return [option.code, brackets.map((bracketText, index) => createReference(option.code, bracketText, index, existing[index]))] })) } catch { return {} } }
function ensureReferences(code) { if (!code || referencesByOption.value[code]) return; const option = article25.options.find((item) => item.code === code); referencesByOption.value[code] = extractBracketedSegments(option?.legalText || '').map((bracketText, index) => createReference(code, bracketText, index)) }
selectedOptionCodes.value.forEach(ensureReferences)
function resolveReference(reference) { if (!reference) return ''; if (reference.source === 'custom') return reference.customReference?.trim() || ''; return reference.choices?.find((choice) => choice.value === reference.source)?.replacement || '' }
function renderOptionPreview(code) { const option = article25.options.find((item) => item.code === code); const references = referencesByOption.value[code] || []; let index = 0; return replaceBracketedSegments(option?.legalText || '', () => resolveReference(references[index++]) || '[Reference required]') }
function updateSelectedReferences(references) { const grouped = {}; references.forEach((reference) => { if (!grouped[reference.optionCode]) grouped[reference.optionCode] = []; grouped[reference.optionCode].push(reference) }); referencesByOption.value = { ...referencesByOption.value, ...grouped } }
function toggleOption(code) { if (selectedOptionCodes.value.includes(code)) { selectedOptionCodes.value = selectedOptionCodes.value.filter((item) => item !== code); return } if ((code === 'A' && selectedOptionCodes.value.includes('F')) || (code === 'F' && selectedOptionCodes.value.includes('A'))) { notify('Option A and Option F cannot be selected together.'); return } ensureReferences(code); selectedOptionCodes.value = [...selectedOptionCodes.value, code]; scheduleHighlight() }
function clearOptions() { selectedOptionCodes.value = [] }
function openPreviewDialog() { previewDialogOpen.value = true; scheduleHighlight() }
function saveDraft() { localStorage.setItem('article-2.5-updated-at', new Date().toISOString()); if (selectedOptionCodes.value.length) localStorage.setItem('article-2.5-options-v1', JSON.stringify(selectedOptionCodes.value)); else localStorage.removeItem('article-2.5-options-v1'); localStorage.setItem('article-2.5-references-v1', JSON.stringify(referencesByOption.value)); localStorage.removeItem('article-2.5-completed'); article25Completed.value = false; notify('Article 2.5 draft saved.') }
function saveAndContinue() { if (!canCompleteArticle.value) return; localStorage.setItem('article-2.5-options-v1', JSON.stringify(selectedOptionCodes.value)); localStorage.setItem('article-2.5-references-v1', JSON.stringify(referencesByOption.value)); localStorage.setItem('article-2.5-completed', 'true'); localStorage.setItem('article-2.5-updated-at', new Date().toISOString()); article25Completed.value = true; router.push('/drafting-workspace') }
function highlightUnresolvedReferences() { document.querySelectorAll('.preview-legal-text, .preview-dialog-legal-text').forEach((container) => container.querySelectorAll('span').forEach((span) => { if (!span.textContent.includes('[Reference required]') || span.querySelector('mark.unresolved-reference')) return; const fragment = document.createDocumentFragment(); span.textContent.split('[Reference required]').forEach((part, index, parts) => { if (part) fragment.appendChild(document.createTextNode(part)); if (index < parts.length - 1) { const marker = document.createElement('mark'); marker.className = 'unresolved-reference'; marker.textContent = '[Reference required]'; fragment.appendChild(marker) } }); span.replaceChildren(fragment) })) }
function scheduleHighlight() { nextTick(() => window.setTimeout(highlightUnresolvedReferences, 0)) }
onMounted(scheduleHighlight)
onUpdated(scheduleHighlight)
function notify(message) { $q.notify({ message, color: 'dark', position: 'top', timeout: 1800 }) }
</script>
